INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'desert-motors-insights-1', 'Desert Motors Industry Brief #1: Full ECU & Suspension Inspection', 'تقرير محركات الصحراء التخصصي #1: فحص كمبيوتر ونظام التعليق الشامل', 'Key operational benchmarks and best practices from Desert Motors in Salmabad.', 'أبرز المعايير التشغيلية وأفضل الممارسات من محركات الصحراء في Salmabad.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Authorized 4x4 service center and spare parts distributor specializing in off-road suspension, ceramic detailing, and OEM parts. Our Full ECU & Suspension Inspection division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مركز خدمة معتمد لسيارات الدفع الرباعي وموزع قطع غيار أصلية وتجهيزات الرحلات. يساعد قسم فحص كمبيوتر ونظام التعليق الشامل المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Authorized 4x4 service center and spare parts distributor specializing in off-road suspension, ceramic detailing, and OEM parts.</p><p>Our Full ECU & Suspension Inspection division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>مركز خدمة معتمد لسيارات الدفع الرباعي وموزع قطع غيار أصلية وتجهيزات الرحلات.</p><p>يساعد قسم فحص كمبيوتر ونظام التعليق الشامل المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'automotive', '{"automotive","Salmabad","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '9 days', true, now() - interval '9 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How do we engage Desert Motors for a new project?', 'كيف يمكننا البدء بمشروع جديد مع محركات الصحراء؟', 'Contact Desert Motors at service@desertmotors.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر service@desertmotors.bh أو إرسال طلب إلكتروني وسيرد فريق محركات الصحراء خلال يوم عمل واحد.', 'general', true, 1, now()) ON CONFLICT (id) DO NOTHING;
